import{_ as n}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as i}from"./chunks/OFF.BrU7kQE-.js";import{_ as s,a as r,b as l,c}from"./chunks/M-S-SW-AW-XP24.ELkzeA7z.js";import{_ as d}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as h,o as p,c as m,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const F=JSON.parse('{"title":"Android Wear","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/wear.md","filePath":"smartwatch/wear.md"}'),w={name:"smartwatch/wear.md"};function b(g,o,y,f,v,x){return p(),m("div",null,[...o[0]||(o[0]=[u('<p>You will find the reference documentation <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">here</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Smart Watch Features<br>   Android Wear Integration</p></div><p>Once you have installed xDrip on the watch paired with your phone, you can enable Wear.<br> xDrip will then communicate with a reduced version of itself on the watch.</p><div class="admonition xdripitem"><p class="admonition-title">Android Wear Integration <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Send data to Android Wear Watchface</p></div><p>For a few combinations of sensors and smartwatch, xDrip can be used directly from the watch itself without needing the phone&#39;s presence. See below for more information.</p><p>Enable wear allows the watch to take over from the phone when the phone xDrip is losing connection to the sensor/bridge.</p><div class="admonition xdripitem"><p class="admonition-title">Enable Wear Collection Service <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Connect Wear to BT Collector when phone is out-of-range</p></div><p>Force wear forces the watch to act as the main device connected to the sensor/bridge even if the phone is nearby (recommended).</p><div class="admonition xdripitem"><p class="admonition-title">Force Wear Collection Service <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Force phone to use Wear Collection Service</p></div><p>Disable force on low battery will make the watch drop sensor/bridge connection to give it back to the phone when its battery level is too low.</p><div class="admonition xdripitem"><p class="admonition-title">Disable Force on Low Battery <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Disable Force Wear Collection Service on Wear low battery alert</p></div><p>Disable force on missed readings will make the watch drop sensor/bridge connection to give it back to the phone after a certain time of missed readings, defined in the menu below.</p><div class="admonition xdripitem"><p class="admonition-title">Disable Force on Missed Readings <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Disable Force Wear Collection Service on minutes since last reading from Wear</p></div><p>Only use wear can be enabled if you have set up the watch once but will not use your phone to connect to the sensor/bridge.</p><div class="admonition xdripitem"><p class="admonition-title">Only use Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>If you plan to only use a Wear collector and never your phone.</p></div><p>If you have several Android Wear smartwatches with xDrip, you can select which one will be the collector. The others will only display xDrip data.</p><div class="admonition xdripitem"><p class="admonition-title">Device running Collection Service</p></div><div class="info custom-block"><p class="custom-block-title">Switching watch</p><p>When switching between watches, xDrip might not be able to communicate its intention to both watches if one is switched off. If you want to change the collecting watch, force collector in xDrip and also force collector in the watch xDrip Prefs menu.</p></div><p>Sync wear logs is a very useful feature when troubleshooting: it will add the watch logs in xDrip <a href="./../use/3dotsmenu.html#events-log">events log</a> with a prefix to identify the activity is on the watch. By default the prefix is <code>wear</code> but you can customize it. It is recommended to keep it enabled.</p><div class="admonition xdripitem"><p class="admonition-title">Sync Wear Logs <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Send Wear logs to Event Viewer</p></div><p>Show treatments adds treatment symbols on the watch graph.</p><div class="admonition xdripitem"><p class="admonition-title">Show Treatments <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Show Treatment points on graph</p></div><h2 id="standalone-collector-mode" tabindex="-1">Standalone collector mode <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;Standalone collector mode&quot;">​</a></h2><p>The xDrip wear extension also contains the part of xDrip that connects to some sensors, meaning you can make the watch act in lieu of the phone and take ownership of the communication and readings, without having your phone nearby.</p><p>This feature is not available for all sensors, see the table below:</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Wear 1.x</th><th>Wear 2.x</th><th>Wear 3+</th></tr></thead><tbody><tr><td>G5/G6/1</td><td>Yes</td><td>Limited*</td><td>No</td></tr><tr><td>G7/1+</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Libre 1 with bridge</td><td>Yes</td><td>Yes</td><td></td></tr><tr><td>Libre 14 days US with bridge</td><td>Yes**</td><td>Yes**</td><td></td></tr><tr><td>Libre 2/2+ EU without bridge</td><td>No</td><td>No</td><td></td></tr><tr><td>Libre 2/2+ EU with bridge</td><td>Yes**</td><td>Yes**</td><td></td></tr></tbody></table><p><em><strong>Limited*:</strong></em> There are some bugs present on most Android Wear smartwatches which prevent them working correctly with the G5/G6. In the best case scenario you will have a reading every 10 minutes. Some watches could be <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">patched</a> to achieve 5-minute readings.</p><div class="info custom-block"><p class="custom-block-title">Why can&#39;t my watch collect from a G5/G6 on its own?</p><p>Most Android Wear watches ship with Bluetooth firmware bugs that break the G5/G6 connection cycle, so the watch misses readings or only gets one every 10 minutes. The only fix found was to patch the watch firmware itself: unlock the bootloader and flash a patch through a custom recovery. This voids the warranty and only exists for a handful of older watches (Asus Zenwatch 2/3, Huawei Watch and Watch 2, LG G Watch, Polar M600). The full explanation, the list of supported watches and the &quot;care pack&quot; downloads are in the <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">Patching Android Wear devices for use with the G5</a> wiki page. If your watch isn&#39;t listed, it can&#39;t collect from a G5/G6 natively: use it as a display for the phone instead.</p></div><p><em><strong>Yes**:</strong></em> You need to have a phone working with <a href="./../use/OOP.html">OOP1</a> or <a href="./../use/OOP.html#oop2">OOP2</a> and also need that same OOP app <a href="./../troubleshoot/ADB.html#smartwatch">sideloaded</a> to your watch. Some bridges might not be compatible.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>The feature is available for sensor/watch combinations described above.</p><p>xDrip extension is installed on the watch with the same version as the one on your phone.</p><p>xDrip connectivity is good on your phone (meaning Bluetooth parameters are correctly defined).</p><p>xDrip on the watch must be authorized to access location.<br><img src="'+s+'" style="zoom:75%;"></p><h3 id="recommended-sequence" tabindex="-1">Recommended sequence <a class="header-anchor" href="#recommended-sequence" aria-label="Permalink to &quot;Recommended sequence&quot;">​</a></h3><p>First time attempt or failure recovery:</p><p>1 - On your phone xDrip: disable force collector, then disable collection, then disable Wear in this order.</p><div class="admonition xdripitem"><p class="admonition-title">Force Wear Collection Service <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Enable Wear Collection Service <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Android Wear Integration <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>2 - Enable wear logs.</p><div class="admonition xdripitem"><p class="admonition-title">Sync Wear Logs <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Send Wear logs to Event Viewer</p></div><p>3 - Restart your smartwatch. Wait until it&#39;s fully running.</p><p>4 - On your phone enable only Wear.</p><div class="admonition xdripitem"><p class="admonition-title">Android Wear Integration <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>5 - Wait until the xDrip graph is fully displayed on the watch (waiting for a new measurement doesn&#39;t hurt).</p><p>6 - Make sure you keep phone, watch and sensor close together and enable first collection then force collector.</p><div class="admonition xdripitem"><p class="admonition-title">Enable Wear Collection Service <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Force Wear Collection Service <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>7 - Pairing process will take typically 10 minutes, open the phone xDrip event logs and wait for events starting with <code>wear</code>.<br><img src="'+r+'" style="zoom:75%;"></p><p>8 - If things went smoothly you should now have the watch in standalone mode.</p><h5 id="if-the-watch-doesnt-connect-to-the-bridge" tabindex="-1">If the watch doesn&#39;t connect to the bridge: <a class="header-anchor" href="#if-the-watch-doesnt-connect-to-the-bridge" aria-label="Permalink to &quot;If the watch doesn&#39;t connect to the bridge:&quot;">​</a></h5><ul><li>In the watch xDrip Prefs menu, check Force Collector.<br><img src="'+l+'" style="zoom:75%;"></li><li>From the xDrip watchface 3 dots menu, Restart Collector.<br><img src="'+d+'" style="zoom:75%;"></li><li>In the watch Bluetooth settings, find your bridge device and pretend to pair it (you can&#39;t pair Miaomiao with the watch but it will try to establish a link to it). After pairing fails, wait 10 minutes for readings to show up.</li><li>If readings don&#39;t appear, disable Force collector and retry the sequence.</li></ul><h2 id="sharing-data-in-standalone-mode" tabindex="-1">Sharing data in standalone mode <a class="header-anchor" href="#sharing-data-in-standalone-mode" aria-label="Permalink to &quot;Sharing data in standalone mode&quot;">​</a></h2><p>If you want the watch to share data (xDrip Sync, Nightscout, ...) it needs to be connected to your phone and your phone needs to be connected to the internet.</p><p>This doesn&#39;t mean they need to be in the same place but the watch itself will not share data directly: it will send them to your phone, and it is your phone that will share. If the watch is connected to the internet through Wi-Fi or a SIM with a data plan, it will need to send them to your phone (connected to the internet also) and your phone itself will share the data. As long as they are both connected to the internet they don&#39;t need to be close to each other.</p><img src="'+c+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',59)])])}const I=h(w,[["render",b]]);export{F as __pageData,I as default};
